CREATE OR REPLACE FUNCTION public.guest_outfit_ids(_member uuid) RETURNS SETOF uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM invite_codes c WHERE c.id=_member AND (is_my_household(c.household,c.invite_id) OR is_celebration_host(c.invite_id))) THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN QUERY SELECT o.id FROM outfits o JOIN invite_codes c ON c.id=_member AND c.invite_id=o.invite_id WHERE member_outfit_allowed(c.id,o.id) OR EXISTS(SELECT 1 FROM reservations r WHERE r.outfit_id=o.id AND r.member_code_id=c.id); END $$;